import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane for the card texture
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture (imageUrl)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Render text items
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2',
      align: 'left',
    });
    // Slightly lift text above the plane to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // GSAP timelines for interactions
  const timelines = [];

  // Hover lift (rise‑in)
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(root.position, {
    y: root.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(hoverTL);

  // Click press‑down
  const clickTL = gsap.timeline({ paused: true });
  clickTL.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1)',
  });
  timelines.push(clickTL);

  // Event handlers
  root.userData.handlers = {
    hover: () => {
      hoverTL.restart();
    },
    click: () => {
      clickTL.restart();
      ctx.emit('navigate', { to: 'hub-journal' });
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
  };

  return root;
}
